css:
.pr { max-width: none; }
.pr > .os-rich { max-width: none; }
.pr > *, .pr > .os-rich > * { margin: 0; max-width: 62ch; }
.pr > * + *, .pr > .os-rich > * + * { margin-top: 1.1em; }
.pr > ul, .pr > ol, .pr > .os-rich > ul, .pr > .os-rich > ol { padding-left: 1.2rem; max-width: none; }
.pr li { margin-top: .5em; max-width: 62ch; }
.pr > h2, .pr > .os-rich > h2 { margin-top: 1.8em; margin-bottom: .5em; font-size: clamp(1.6rem, 1.1rem + 1.6vw, 2.3rem); line-height: 1.08; letter-spacing: -.015em; }
.pr > h2:last-child, .pr > .os-rich > h2:last-child { --keep: 1; font-weight: 400; letter-spacing: 0; font-size: clamp(2rem, 1rem + 3.4vw, 3.8rem); line-height: 1.12; max-width: 18ch; margin-top: clamp(2.2rem, 5vw, 3.6rem); margin-bottom: 0; text-wrap: wrap; }
.pr > h3, .pr > .os-rich > h3 { margin-top: 1.2em; font-size: 1.25rem; }

